<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Builder; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\BelongsToMany; use Illuminate\Database\Eloquent\Relations\HasMany;
class AdvertisingCampaign extends Model { use HasFactory,SoftDeletes; const STATUSES=['draft','submitted','approved','scheduled','active','paused','completed','rejected','canceled']; protected $fillable=['uuid','advertiser_id','name','public_code','status','objective','pricing_model','budget_cents','contract_value_cents','impression_goal','click_goal','starts_at','ends_at','submitted_at','approved_at','approved_by','rejection_reason','internal_notes']; protected $casts=['starts_at'=>'datetime','ends_at'=>'datetime','submitted_at'=>'datetime','approved_at'=>'datetime','budget_cents'=>'integer','contract_value_cents'=>'integer']; public function advertiser(): BelongsTo{return $this->belongsTo(Advertiser::class);} public function approver(): BelongsTo{return $this->belongsTo(User::class,'approved_by');} public function placements(): BelongsToMany{return $this->belongsToMany(AdPlacement::class,'advertising_campaign_placement')->withPivot(['priority','allocated_budget_cents'])->withTimestamps();} public function creatives(): HasMany{return $this->hasMany(AdCreative::class);} public function scopeCurrent(Builder $q): Builder{return $q->where('status','active')->where(fn($q)=>$q->whereNull('starts_at')->orWhere('starts_at','<=',now()))->where(fn($q)=>$q->whereNull('ends_at')->orWhere('ends_at','>=',now()));} }
